<?php
declare(strict_types=1); namespace App\Services\Academic;
use App\Models\LessonSchedule; use Carbon\CarbonImmutable; use Illuminate\Validation\ValidationException;
class LessonScheduleService { public function ensureNoConflict(array $data,?int $ignore=null):void{$q=LessonSchedule::query()->where('classroom_id',$data['classroom_id'])->where('semester_id',$data['semester_id'])->where('day_of_week',$data['day_of_week'])->where('active',true)->where('start_time','<',$data['end_time'])->where('end_time','>',$data['start_time']); if($ignore)$q->whereKeyNot($ignore); if($q->exists())throw ValidationException::withMessages(['start_time'=>'Jadwal kelas bertabrakan dengan pelajaran lain.']);} public function currentAndNext(int $classroomId,int $semesterId,?CarbonImmutable $at=null):array{$at=($at??CarbonImmutable::now('Asia/Jakarta'))->setTimezone('Asia/Jakarta');$q=LessonSchedule::with(['subject','personnel','classroom'])->where('classroom_id',$classroomId)->where('semester_id',$semesterId)->where('day_of_week',$at->dayOfWeekIso)->where('active',true)->orderBy('start_time')->get();$time=$at->format('H:i:s');return ['current'=>$q->first(fn($s)=>$s->start_time<=$time&&$s->end_time>$time),'next'=>$q->first(fn($s)=>$s->start_time>$time),'timeline'=>$q];} }
